const incoming = $input.first()?.json ?? {};
const payload = incoming.body ?? incoming;
const data = payload.data ?? {};
const key = data.key ?? {};
const message = data.message ?? {};
const primaryJid = String(key.remoteJid ?? '');
const alternateJid = String(key.remoteJidAlt ?? '');
const event = String(payload.event ?? '').toLowerCase().replace(/_/g, '.');
const fromMe = key.fromMe === true || key.fromMe === 'true';
const isGroup = primaryJid.endsWith('@g.us');
const isBroadcast = primaryJid === 'status@broadcast' || primaryJid.endsWith('@broadcast');
const jidForNumber = primaryJid.endsWith('@lid') && alternateJid ? alternateJid : primaryJid;
const number = jidForNumber.split('@')[0].split(':')[0].replace(/\D/g, '');
const instance = String(payload.instance ?? '');
const messageType = String(data.messageType ?? Object.keys(message)[0] ?? '').toLowerCase();
const text = String(
  message.conversation ??
  message.extendedTextMessage?.text ??
  message.imageMessage?.caption ??
  message.videoMessage?.caption ??
  message.documentMessage?.caption ??
  ''
).trim();
const isMessagesUpsert = !event || event.includes('messages.upsert');
const hasMessage = Object.keys(message).length > 0;
const usableJid = !primaryJid.endsWith('@lid') || Boolean(alternateJid);
const validNumber = usableJid && number.length >= 7 && number.length <= 15;
const shouldReply = isMessagesUpsert && !fromMe && !isGroup && !isBroadcast && validNumber && Boolean(instance) && hasMessage;
const messageText = text || (shouldReply ? '[رسالة غير نصية]' : '');

return [{
  json: {
    shouldReply,
    number,
    instance,
    customerName: String(data.pushName ?? ''),
    messageType,
    messageText
  }
}];
